import{_ as t,c as h,o as a,a2 as i}from"./chunks/framework.B7el9cAC.js";const d=JSON.parse('{"title":"Mục 2.6 – Bảo Mật Thông Tin Trên Mạng","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-2/2.6-bao-mat-mang.md","filePath":"chuong-2/2.6-bao-mat-mang.md","lastUpdated":1775359730000}'),o={name:"chuong-2/2.6-bao-mat-mang.md"};function g(r,n,s,c,e,l){return a(),h("div",null,[...n[0]||(n[0]=[i(`<h1 id="muc-2-6-–-bao-mat-thong-tin-tren-mang" tabindex="-1">Mục 2.6 – Bảo Mật Thông Tin Trên Mạng <a class="header-anchor" href="#muc-2-6-–-bao-mat-thong-tin-tren-mang" aria-label="Permalink to &quot;Mục 2.6 – Bảo Mật Thông Tin Trên Mạng&quot;">​</a></h1><blockquote><p><strong>Chương 2: Mạng máy tính và Internet</strong></p></blockquote><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><h3 id="tai-sao-can-bao-mat-thong-tin-tren-mang" tabindex="-1">Tại sao cần bảo mật thông tin trên mạng? <a class="header-anchor" href="#tai-sao-can-bao-mat-thong-tin-tren-mang" aria-label="Permalink to &quot;Tại sao cần bảo mật thông tin trên mạng?&quot;">​</a></h3><p>Hãy tưởng tượng bạn viết nhật ký và để lên bàn giữa phòng – ai đi qua cũng đọc được. Đó chính xác là điều xảy ra khi bạn gửi dữ liệu qua mạng <strong>mà không có bảo mật</strong>.</p><p>Trong thế giới số ngày nay:</p><ul><li>Thông tin cá nhân, tài khoản ngân hàng, mật khẩu của bạn đều đi qua mạng.</li><li>Có hàng triệu kẻ xấu (hacker, tội phạm mạng) đang chờ cơ hội đánh cắp.</li><li>Một vụ rò rỉ dữ liệu có thể gây thiệt hại tài chính, danh dự, thậm chí ảnh hưởng đến an ninh quốc gia.</li></ul><p><strong>Bảo mật thông tin</strong> là tập hợp các biện pháp kỹ thuật và phi kỹ thuật nhằm bảo vệ thông tin khỏi:</p><ul><li><strong>Truy cập trái phép</strong> (Unauthorized Access)</li><li><strong>Sửa đổi trái phép</strong> (Unauthorized Modification)</li><li><strong>Phá hoại, từ chối dịch vụ</strong> (Disruption/Denial)</li></ul><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="_2-1-cac-moi-đe-doa-bao-mat-pho-bien" tabindex="-1">2.1 Các mối đe dọa bảo mật phổ biến <a class="header-anchor" href="#_2-1-cac-moi-đe-doa-bao-mat-pho-bien" aria-label="Permalink to &quot;2.1 Các mối đe dọa bảo mật phổ biến&quot;">​</a></h3><h4 id="🦠-phan-mem-đoc-hai-malware" tabindex="-1">🦠 Phần mềm độc hại (Malware) <a class="header-anchor" href="#🦠-phan-mem-đoc-hai-malware" aria-label="Permalink to &quot;🦠 Phần mềm độc hại (Malware)&quot;">​</a></h4><p><strong>Malware (Malicious Software)</strong> là thuật ngữ chung chỉ mọi phần mềm được tạo ra với mục đích gây hại.</p><table tabindex="0"><thead><tr><th>Loại</th><th>Đặc điểm</th><th>Cách lây lan</th><th>Tác hại</th></tr></thead><tbody><tr><td><strong>Virus</strong></td><td>Gắn vào file, cần người dùng chạy để lây</td><td>File đính kèm email, USB</td><td>Xóa/sửa file, làm chậm máy</td></tr><tr><td><strong>Worm</strong></td><td>Tự nhân bản, lây qua mạng không cần người dùng</td><td>Lỗ hổng mạng, email</td><td>Chiếm băng thông, tắc nghẽn mạng</td></tr><tr><td><strong>Trojan</strong></td><td>Giả dạng phần mềm hợp lệ</td><td>Tải phần mềm lậu, crack</td><td>Mở cửa hậu cho hacker</td></tr><tr><td><strong>Ransomware</strong></td><td>Mã hóa dữ liệu, đòi tiền chuộc</td><td>Email, website giả</td><td>Mất dữ liệu, thiệt hại tài chính</td></tr><tr><td><strong>Spyware</strong></td><td>Theo dõi hoạt động người dùng ngầm</td><td>Phần mềm miễn phí không rõ nguồn</td><td>Đánh cắp mật khẩu, thói quen duyệt web</td></tr><tr><td><strong>Adware</strong></td><td>Hiển thị quảng cáo không mong muốn</td><td>Phần mềm miễn phí</td><td>Làm chậm máy, phiền nhiễu</td></tr></tbody></table><h4 id="🎣-tan-cong-phishing-gia-mao" tabindex="-1">🎣 Tấn công Phishing (Giả mạo) <a class="header-anchor" href="#🎣-tan-cong-phishing-gia-mao" aria-label="Permalink to &quot;🎣 Tấn công Phishing (Giả mạo)&quot;">​</a></h4><p><strong>Phishing</strong> là kỹ thuật <strong>giả mạo</strong> email, website, tin nhắn của tổ chức uy tín (ngân hàng, Google, Facebook...) để lừa người dùng cung cấp thông tin nhạy cảm.</p><p><strong>Dấu hiệu nhận biết Phishing:</strong></p><ul><li>URL lạ: <code>g00gle.com</code> thay vì <code>google.com</code>, <code>bank-vietcombank.net</code> thay vì <code>vietcombank.com.vn</code></li><li>Lỗi chính tả, ngữ pháp kém trong email.</li><li>Yêu cầu khẩn cấp: &quot;Tài khoản bạn sẽ bị khóa trong 24 giờ nếu không xác minh!&quot;</li><li>Yêu cầu cung cấp mật khẩu, mã OTP qua email/tin nhắn (ngân hàng thật <strong>không bao giờ</strong> hỏi điều này).</li></ul><h4 id="💥-tan-cong-ddos-tu-choi-dich-vu-phan-tan" tabindex="-1">💥 Tấn công DDoS (Từ chối dịch vụ phân tán) <a class="header-anchor" href="#💥-tan-cong-ddos-tu-choi-dich-vu-phan-tan" aria-label="Permalink to &quot;💥 Tấn công DDoS (Từ chối dịch vụ phân tán)&quot;">​</a></h4><p><strong>DDoS (Distributed Denial of Service)</strong> là tấn công làm cho máy chủ/website <strong>không thể phục vụ người dùng hợp lệ</strong> bằng cách gửi hàng triệu yêu cầu giả mạo cùng lúc.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Hacker]</span></span>
<span class="line"><span>    ↓ điều khiển</span></span>
<span class="line"><span>[Botnet – hàng nghìn máy tính bị nhiễm]</span></span>
<span class="line"><span>    ↓ tất cả gửi request đồng loạt</span></span>
<span class="line"><span>[Máy chủ mục tiêu] → QUÁ TẢI → SẬP</span></span></code></pre></div><p><strong>Hậu quả:</strong> Website/dịch vụ ngừng hoạt động. Thiệt hại: doanh nghiệp thương mại điện tử mất hàng trăm triệu đồng/giờ khi sập dịch vụ.</p><h4 id="👤-tan-cong-man-in-the-middle-mitm" tabindex="-1">👤 Tấn công Man-in-the-Middle (MITM) <a class="header-anchor" href="#👤-tan-cong-man-in-the-middle-mitm" aria-label="Permalink to &quot;👤 Tấn công Man-in-the-Middle (MITM)&quot;">​</a></h4><p>Kẻ tấn công <strong>chèn mình vào giữa</strong> hai bên giao tiếp, nghe lén và có thể sửa đổi dữ liệu mà cả hai bên không hay biết.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BẠN  ←→  [KẺ TẤN CÔNG]  ←→  NGÂN HÀNG</span></span>
<span class="line"><span>         (nghe lén tất cả,</span></span>
<span class="line"><span>          có thể sửa dữ liệu)</span></span></code></pre></div><p><strong>Xảy ra nhiều nhất khi:</strong> Dùng Wi-Fi công cộng không bảo mật. <strong>Phòng tránh:</strong> Dùng HTTPS, VPN.</p><h3 id="_2-2-cac-bien-phap-bao-mat" tabindex="-1">2.2 Các biện pháp bảo mật <a class="header-anchor" href="#_2-2-cac-bien-phap-bao-mat" aria-label="Permalink to &quot;2.2 Các biện pháp bảo mật&quot;">​</a></h3><h4 id="🔐-ma-hoa-du-lieu-encryption" tabindex="-1">🔐 Mã hóa dữ liệu (Encryption) <a class="header-anchor" href="#🔐-ma-hoa-du-lieu-encryption" aria-label="Permalink to &quot;🔐 Mã hóa dữ liệu (Encryption)&quot;">​</a></h4><p><strong>Mã hóa</strong> là quá trình <strong>biến dữ liệu dễ đọc thành dạng không đọc được</strong> (ciphertext) trừ khi có khóa giải mã.</p><p><strong>Ví dụ đơn giản (Caesar cipher):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Văn bản gốc: HELLO</span></span>
<span class="line"><span>Dịch chuyển 3: KHOOR</span></span>
<span class="line"><span>→ Nếu không có &quot;khóa&quot; (biết phải dịch lại 3), không đọc được</span></span></code></pre></div><p><strong>Mã hóa hiện đại:</strong></p><table tabindex="0"><thead><tr><th>Loại</th><th>Ví dụ</th><th>Đặc điểm</th></tr></thead><tbody><tr><td><strong>Đối xứng</strong> (Symmetric)</td><td>AES, DES</td><td>Cùng 1 khóa để mã hóa và giải mã – nhanh</td></tr><tr><td><strong>Bất đối xứng</strong> (Asymmetric)</td><td>RSA, ECC</td><td>Khóa công khai mã hóa, khóa riêng tư giải mã – an toàn hơn</td></tr><tr><td><strong>Hàm băm</strong> (Hash)</td><td>MD5, SHA-256</td><td>Một chiều, không giải mã được – dùng kiểm tra toàn vẹn</td></tr></tbody></table><p><strong>SSL/TLS</strong> (Secure Sockets Layer / Transport Layer Security) là giao thức mã hóa bảo vệ dữ liệu truyền giữa trình duyệt và máy chủ web – nền tảng của HTTPS.</p><h4 id="🧱-tuong-lua-firewall" tabindex="-1">🧱 Tường lửa (Firewall) <a class="header-anchor" href="#🧱-tuong-lua-firewall" aria-label="Permalink to &quot;🧱 Tường lửa (Firewall)&quot;">​</a></h4><p><strong>Firewall</strong> là hệ thống (phần cứng hoặc phần mềm) <strong>kiểm soát luồng dữ liệu</strong> vào/ra mạng, cho phép hoặc chặn dựa trên quy tắc được cấu hình.</p><ul><li><strong>Firewall phần cứng:</strong> Router cao cấp trong doanh nghiệp có tích hợp firewall.</li><li><strong>Firewall phần mềm:</strong> Windows Firewall, iptables trên Linux.</li></ul><p><strong>Nguyên tắc hoạt động:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Mạng ngoài/Internet]</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>     [FIREWALL]</span></span>
<span class="line"><span>     ├── Gói tin từ IP đáng tin cậy, cổng hợp lệ → CHO QUA ✅</span></span>
<span class="line"><span>     └── Gói tin từ IP lạ, cổng nguy hiểm, giao thức bị chặn → CHẶN ❌</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>     [Mạng nội bộ]</span></span></code></pre></div><p><strong>Bộ lọc firewall có thể dựa trên:</strong></p><ul><li>Địa chỉ IP nguồn/đích</li><li>Cổng nguồn/đích (port)</li><li>Giao thức (TCP, UDP, ICMP)</li><li>Nội dung gói tin (Deep Packet Inspection)</li></ul><h4 id="🛡️-phan-mem-diet-virus-antivirus-anti-malware" tabindex="-1">🛡️ Phần mềm diệt virus (Antivirus/Anti-malware) <a class="header-anchor" href="#🛡️-phan-mem-diet-virus-antivirus-anti-malware" aria-label="Permalink to &quot;🛡️ Phần mềm diệt virus (Antivirus/Anti-malware)&quot;">​</a></h4><p>Phần mềm antivirus hoạt động bằng cách:</p><ol><li><strong>Signature scanning:</strong> So sánh file với cơ sở dữ liệu virus đã biết.</li><li><strong>Heuristic analysis:</strong> Phân tích hành vi bất thường của file/chương trình.</li><li><strong>Sandboxing:</strong> Chạy file trong môi trường cách ly để quan sát hành vi.</li><li><strong>Real-time protection:</strong> Giám sát liên tục, cảnh báo ngay khi phát hiện mối đe dọa.</li></ol><p><strong>Phần mềm phổ biến:</strong> Kaspersky, BKAV (Việt Nam), Windows Defender, Bitdefender, Avast.</p><h4 id="🔑-xac-thuc-va-kiem-soat-truy-cap" tabindex="-1">🔑 Xác thực và kiểm soát truy cập <a class="header-anchor" href="#🔑-xac-thuc-va-kiem-soat-truy-cap" aria-label="Permalink to &quot;🔑 Xác thực và kiểm soát truy cập&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Phương pháp</th><th>Mô tả</th><th>Ví dụ</th></tr></thead><tbody><tr><td><strong>Mật khẩu</strong> (Password)</td><td>Thứ bạn <strong>biết</strong></td><td>Mật khẩu đăng nhập</td></tr><tr><td><strong>2FA/MFA</strong></td><td>Nhiều yếu tố xác thực</td><td>Mật khẩu + mã OTP SMS</td></tr><tr><td><strong>Sinh trắc học</strong> (Biometric)</td><td>Thứ bạn <strong>có</strong> (về sinh học)</td><td>Vân tay, khuôn mặt, mống mắt</td></tr><tr><td><strong>Certificate</strong></td><td>Chứng chỉ số</td><td>SSL Certificate, Smart Card</td></tr><tr><td><strong>SSO</strong></td><td>Đăng nhập một lần</td><td>&quot;Đăng nhập bằng Google&quot;</td></tr></tbody></table><p><strong>Nguyên tắc mật khẩu mạnh:</strong></p><ul><li>Ít nhất <strong>12 ký tự</strong> (khuyến nghị 15+ ký tự)</li><li>Kết hợp: chữ hoa, chữ thường, số, ký tự đặc biệt</li><li><strong>Không dùng</strong> tên, ngày sinh, &quot;123456&quot;, &quot;password&quot;</li><li><strong>Không dùng chung</strong> mật khẩu cho nhiều tài khoản</li><li>Thay đổi mật khẩu <strong>khi có dấu hiệu bị lộ</strong> (không nên đổi định kỳ theo lịch cố định vì thường dẫn đến mật khẩu yếu hơn)</li></ul><h3 id="_2-3-an-toan-khi-dung-mang" tabindex="-1">2.3 An toàn khi dùng mạng <a class="header-anchor" href="#_2-3-an-toan-khi-dung-mang" aria-label="Permalink to &quot;2.3 An toàn khi dùng mạng&quot;">​</a></h3><p><strong>Nguyên tắc vàng khi dùng Internet:</strong></p><ol><li><strong>Không chia sẻ thông tin cá nhân</strong> nhạy cảm (CMND, tài khoản ngân hàng, mật khẩu) qua mạng nếu không chắc chắn nơi nhận là an toàn.</li><li><strong>Kiểm tra HTTPS</strong> trước khi nhập mật khẩu hoặc thông tin thanh toán.</li><li><strong>Không tải phần mềm</strong> từ nguồn không rõ ràng – chỉ tải từ trang chính thức.</li><li><strong>Cập nhật phần mềm</strong> thường xuyên – bản vá bảo mật đóng các lỗ hổng mà hacker khai thác.</li><li><strong>Sao lưu dữ liệu</strong> định kỳ (backup) – đề phòng ransomware hoặc hỏng ổ cứng.</li><li><strong>Cẩn thận với Wi-Fi công cộng</strong> – tránh giao dịch nhạy cảm khi dùng Wi-Fi miễn phí.</li></ol><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="tai-sao-virus-khac-worm" tabindex="-1">Tại sao Virus khác Worm? <a class="header-anchor" href="#tai-sao-virus-khac-worm" aria-label="Permalink to &quot;Tại sao Virus khác Worm?&quot;">​</a></h3><p><strong>Virus</strong> cần &quot;ký chủ&quot; để tồn tại – giống như virus sinh học, nó gắn vào một file (ký chủ) và chờ người dùng chạy file đó để lây lan. Virus <strong>không tự lan</strong> – cần con người mang đi (copy file, gửi email).</p><p><strong>Worm</strong> tự di chuyển qua mạng – giống như sâu bọ bò, không cần ai giúp. Worm khai thác lỗ hổng mạng để tự sao chép sang máy tính khác mà không cần người dùng làm gì.</p><h3 id="tai-sao-can-2fa-xac-thuc-2-yeu-to" tabindex="-1">Tại sao cần 2FA (Xác thực 2 yếu tố)? <a class="header-anchor" href="#tai-sao-can-2fa-xac-thuc-2-yeu-to" aria-label="Permalink to &quot;Tại sao cần 2FA (Xác thực 2 yếu tố)?&quot;">​</a></h3><p>Mật khẩu có thể bị:</p><ul><li>Đoán (nếu yếu như &quot;123456&quot;)</li><li>Bị lộ qua phishing</li><li>Bị đánh cắp qua malware</li></ul><p>Nhưng nếu sau mật khẩu còn cần <strong>mã OTP gửi vào điện thoại của bạn</strong>, kẻ tấn công dù có mật khẩu cũng không thể đăng nhập nếu không có điện thoại bạn.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Chỉ mật khẩu:    Hacker biết mật khẩu → vào được ❌</span></span>
<span class="line"><span>Mật khẩu + OTP:  Hacker biết mật khẩu nhưng không có điện thoại bạn → không vào được ✅</span></span></code></pre></div><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="kich-ban-tan-cong-phishing-va-cach-phong-tranh" tabindex="-1">Kịch bản tấn công Phishing và cách phòng tránh <a class="header-anchor" href="#kich-ban-tan-cong-phishing-va-cach-phong-tranh" aria-label="Permalink to &quot;Kịch bản tấn công Phishing và cách phòng tránh&quot;">​</a></h3><p><strong>Kịch bản tấn công:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Bước 1] Hacker tạo website giả giống hệt trang ngân hàng VCB</span></span>
<span class="line"><span>          URL: vcb-bank.com.vn (giả) thay vì vietcombank.com.vn (thật)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Bước 2] Hacker gửi email hàng loạt:</span></span>
<span class="line"><span>          &quot;⚠️ Tài khoản VCB của bạn có dấu hiệu đáng ngờ.</span></span>
<span class="line"><span>           Đăng nhập ngay để xác minh: [LINK]&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Bước 3] Người dùng lo lắng → click vào link → vào trang giả</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Bước 4] Nhập username + password + OTP</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Bước 5] Hacker nhận được thông tin, ngay lập tức dùng để đăng nhập vào VCB thật</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Bước 6] Chuyển tiền → Tiền mất!</span></span></code></pre></div><p><strong>Cách phòng tránh:</strong></p><ol><li>Luôn kiểm tra URL: <code>vietcombank.com.vn</code> ✅ vs <code>vcb-bank.com.vn</code> ❌</li><li>Không click link trong email – tự gõ địa chỉ vào trình duyệt.</li><li>Kích hoạt <strong>2FA</strong> – dù bị lộ mật khẩu, hacker cũng không vào được nếu cần OTP thứ 2.</li><li>Ngân hàng <strong>không bao giờ</strong> hỏi mật khẩu qua email/SMS.</li></ol><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-nhan-biet-malware-trong-tinh-huong-thuc-te" tabindex="-1">Ví dụ 1 – Nhận biết malware trong tình huống thực tế <a class="header-anchor" href="#vi-du-1-–-nhan-biet-malware-trong-tinh-huong-thuc-te" aria-label="Permalink to &quot;Ví dụ 1 – Nhận biết malware trong tình huống thực tế&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tình huống</th><th>Loại malware</th></tr></thead><tbody><tr><td>Máy tính đột nhiên hiển thị thông báo &quot;Tất cả file của bạn đã bị mã hóa, trả 0.5 Bitcoin để lấy lại&quot;</td><td>Ransomware</td></tr><tr><td>Cài phần mềm tải nhạc miễn phí, máy tính bỗng chạy quảng cáo liên tục</td><td>Adware</td></tr><tr><td>Tải game crack, mật khẩu email bị thay đổi sau đó</td><td>Trojan/Spyware</td></tr><tr><td>Cả mạng trường học bị chậm do có máy tính liên tục gửi packet</td><td>Worm</td></tr><tr><td>Mở file đính kèm email, các file .docx bắt đầu bị xóa dần</td><td>Virus</td></tr></tbody></table><h3 id="vi-du-2-–-đanh-gia-đo-manh-cua-mat-khau" tabindex="-1">Ví dụ 2 – Đánh giá độ mạnh của mật khẩu <a class="header-anchor" href="#vi-du-2-–-đanh-gia-đo-manh-cua-mat-khau" aria-label="Permalink to &quot;Ví dụ 2 – Đánh giá độ mạnh của mật khẩu&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mật khẩu</th><th>Đánh giá</th><th>Lý do</th></tr></thead><tbody><tr><td><code>123456</code></td><td>❌ Rất yếu</td><td>Quá đơn giản, trong top 10 mật khẩu phổ biến nhất</td></tr><tr><td><code>nguyenvana</code></td><td>❌ Yếu</td><td>Tên người dùng, dễ đoán</td></tr><tr><td><code>NguyenVanA1</code></td><td>⚠️ Trung bình</td><td>Có hoa thường số nhưng chứa tên</td></tr><tr><td><code>Tr@ng!2024#</code></td><td>✅ Khá mạnh</td><td>Hoa, thường, số, ký tự đặc biệt</td></tr><tr><td><code>xK9#mPq@7Yw!</code></td><td>✅✅ Rất mạnh</td><td>Ngẫu nhiên, dài 12+ ký tự, mọi loại ký tự</td></tr></tbody></table><h3 id="vi-du-3-–-firewall-rules-đon-gian" tabindex="-1">Ví dụ 3 – Firewall rules đơn giản <a class="header-anchor" href="#vi-du-3-–-firewall-rules-đon-gian" aria-label="Permalink to &quot;Ví dụ 3 – Firewall rules đơn giản&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Quy tắc Firewall của công ty ABC:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ALLOW  TCP  từ 192.168.1.0/24  đến bất kỳ   cổng 80,443   → Nhân viên duyệt web OK</span></span>
<span class="line"><span>ALLOW  TCP  từ bất kỳ          đến máy chủ   cổng 443      → Khách hàng vào website OK</span></span>
<span class="line"><span>DENY   TCP  từ bất kỳ          đến bất kỳ    cổng 22       → Chặn SSH từ ngoài</span></span>
<span class="line"><span>DENY   UDP  từ bất kỳ          đến bất kỳ    cổng 53       → Chặn DNS từ ngoài</span></span>
<span class="line"><span>DENY   tất cả từ ngoài đến mạng nội bộ                      → Chặn mọi truy cập còn lại</span></span></code></pre></div><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="cac-loai-malware" tabindex="-1">Các loại malware <a class="header-anchor" href="#cac-loai-malware" aria-label="Permalink to &quot;Các loại malware&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Loại</th><th>Tự lan qua mạng?</th><th>Cần file ký chủ?</th><th>Mục tiêu chính</th></tr></thead><tbody><tr><td><strong>Virus</strong></td><td>Không</td><td>Có</td><td>Phá hoại file</td></tr><tr><td><strong>Worm</strong></td><td>Có</td><td>Không</td><td>Lây lan, tắc nghẽn mạng</td></tr><tr><td><strong>Trojan</strong></td><td>Không</td><td>Giả làm phần mềm</td><td>Mở cửa hậu</td></tr><tr><td><strong>Ransomware</strong></td><td>Đôi khi</td><td>Không nhất thiết</td><td>Tống tiền</td></tr><tr><td><strong>Spyware</strong></td><td>Không</td><td>Không nhất thiết</td><td>Thu thập thông tin</td></tr></tbody></table><h3 id="phuong-phap-xac-thuc" tabindex="-1">Phương pháp xác thực <a class="header-anchor" href="#phuong-phap-xac-thuc" aria-label="Permalink to &quot;Phương pháp xác thực&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Phương pháp</th><th>Mức bảo mật</th><th>Tiện lợi</th><th>Ví dụ</th></tr></thead><tbody><tr><td>Mật khẩu đơn</td><td>⭐⭐</td><td>⭐⭐⭐⭐⭐</td><td>Đăng nhập cơ bản</td></tr><tr><td>Mật khẩu + OTP SMS</td><td>⭐⭐⭐⭐</td><td>⭐⭐⭐⭐</td><td>Ngân hàng online</td></tr><tr><td>Mật khẩu + Authenticator app</td><td>⭐⭐⭐⭐⭐</td><td>⭐⭐⭐</td><td>Gmail, GitHub</td></tr><tr><td>Vân tay/Khuôn mặt</td><td>⭐⭐⭐⭐</td><td>⭐⭐⭐⭐⭐</td><td>Điện thoại, laptop</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>🦠 <strong>Virus</strong> = bám vào file, cần người dùng chạy để lây; <strong>Worm</strong> = tự lan qua mạng</li><li>💰 <strong>Ransomware</strong> = mã hóa dữ liệu đòi tiền chuộc</li><li>🎣 <strong>Phishing</strong> = giả mạo tổ chức uy tín để đánh cắp thông tin</li><li>💥 <strong>DDoS</strong> = dùng nhiều máy tấn công cùng lúc → làm sập máy chủ</li><li>🧱 <strong>Firewall</strong> = kiểm soát luồng dữ liệu vào/ra mạng theo quy tắc</li><li>🔐 <strong>Mã hóa</strong> = biến dữ liệu thành dạng không đọc được nếu không có khóa</li><li>🔒 <strong>HTTPS</strong> = HTTP + mã hóa SSL/TLS → bảo vệ dữ liệu truyền tải</li><li>📱 <strong>2FA</strong> = xác thực 2 yếu tố = mật khẩu + OTP/sinh trắc học</li><li>🛡️ <strong>Antivirus</strong> = phát hiện và diệt malware (BKAV là phần mềm Việt Nam)</li><li>✅ Mật khẩu mạnh: <strong>dài 12+ ký tự</strong>, kết hợp hoa/thường/số/ký tự đặc biệt</li><li>❌ Không click link lạ trong email, SMS – dấu hiệu phishing</li><li>💾 Sao lưu dữ liệu thường xuyên để phòng ransomware</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-phan-loai-malware" tabindex="-1">Câu 1 (Dễ): Phân loại malware <a class="header-anchor" href="#cau-1-de-phan-loai-malware" aria-label="Permalink to &quot;Câu 1 (Dễ): Phân loại malware&quot;">​</a></h3><blockquote><p>Phần mềm nào sau đây <strong>tự lan sang máy tính khác qua mạng</strong> mà không cần người dùng thực hiện hành động? A. Virus B. Worm C. Trojan D. Adware</p></blockquote><p><strong>Đáp án: B – Worm</strong></p><p><strong>Giải thích:</strong> Worm (sâu máy tính) có khả năng tự nhân bản và lây lan qua mạng mà <strong>không cần người dùng thực hiện bất kỳ hành động nào</strong>. Nó khai thác lỗ hổng bảo mật của hệ điều hành hoặc ứng dụng mạng. Ngược lại, Virus cần gắn vào file và được người dùng chạy, Trojan giả mạo phần mềm hợp lệ, Adware hiển thị quảng cáo.</p><hr><h3 id="cau-2-de-nhan-biet-tan-cong" tabindex="-1">Câu 2 (Dễ): Nhận biết tấn công <a class="header-anchor" href="#cau-2-de-nhan-biet-tan-cong" aria-label="Permalink to &quot;Câu 2 (Dễ): Nhận biết tấn công&quot;">​</a></h3><blockquote><p>Bạn nhận được email từ &quot;<a href="mailto:support@g00gle.com" target="_blank" rel="noreferrer">support@g00gle.com</a>&quot; thông báo tài khoản Google sẽ bị xóa, yêu cầu click vào link để xác minh mật khẩu ngay lập tức. Đây là loại tấn công gì? Bạn nên làm gì?</p></blockquote><p><strong>Đáp án:</strong> Đây là tấn công <strong>Phishing</strong> (giả mạo).</p><p><strong>Dấu hiệu:</strong></p><ul><li>Email từ <code>g00gle.com</code> (dùng số 0 thay chữ o) – không phải <code>google.com</code></li><li>Tạo cảm giác khẩn cấp (&quot;tài khoản sẽ bị xóa&quot;)</li><li>Yêu cầu cung cấp mật khẩu</li></ul><p><strong>Cách xử lý:</strong></p><ol><li>Không click vào link.</li><li>Xóa email.</li><li>Nếu lo lắng, tự gõ <code>accounts.google.com</code> vào trình duyệt để kiểm tra tài khoản thật.</li><li>Báo email là spam/phishing cho nhà cung cấp email.</li></ol><hr><h3 id="cau-3-trung-binh-phan-tich-tinh-huong-bao-mat" tabindex="-1">Câu 3 (Trung bình): Phân tích tình huống bảo mật <a class="header-anchor" href="#cau-3-trung-binh-phan-tich-tinh-huong-bao-mat" aria-label="Permalink to &quot;Câu 3 (Trung bình): Phân tích tình huống bảo mật&quot;">​</a></h3><blockquote><p>Công ty A bị tấn công: website ngừng hoạt động 3 tiếng vì server nhận hàng triệu request từ hàng nghìn địa chỉ IP khác nhau trên toàn thế giới trong cùng một lúc. Đây là loại tấn công gì? Giải thích cơ chế.</p></blockquote><p><strong>Đáp án:</strong> Tấn công <strong>DDoS (Distributed Denial of Service)</strong>.</p><p><strong>Giải thích cơ chế:</strong></p><ul><li>Hacker kiểm soát một <strong>botnet</strong> (mạng lưới hàng nghìn/triệu máy tính đã bị nhiễm malware trên toàn thế giới).</li><li>Ra lệnh cho toàn bộ botnet gửi request đến server của công ty A cùng lúc.</li><li>Server bị <strong>quá tải</strong>, không thể xử lý request hợp lệ từ khách hàng thật → từ chối dịch vụ.</li><li>Vì request đến từ nhiều IP khác nhau (không phải một IP duy nhất), rất khó chặn.</li><li><strong>Đặc điểm nhận biết:</strong> Request đến từ hàng nghìn IP phân tán khắp thế giới, cùng một lúc, khác hành vi bình thường.</li></ul><hr><h3 id="cau-4-trung-binh-giai-thich-ma-hoa" tabindex="-1">Câu 4 (Trung bình): Giải thích mã hóa <a class="header-anchor" href="#cau-4-trung-binh-giai-thich-ma-hoa" aria-label="Permalink to &quot;Câu 4 (Trung bình): Giải thích mã hóa&quot;">​</a></h3><blockquote><p>Hãy giải thích tại sao cần dùng HTTPS thay vì HTTP khi truy cập trang web ngân hàng. Điều gì xảy ra nếu dùng HTTP?</p></blockquote><p><strong>Đáp án:</strong></p><p><strong>Nếu dùng HTTP (không mã hóa):</strong></p><ul><li>Dữ liệu truyền đi ở dạng <strong>văn bản thuần túy (plaintext)</strong>.</li><li>Bất kỳ ai có thể nghe lén mạng (ví dụ: kẻ tấn công trong cùng Wi-Fi) có thể đọc được: tên đăng nhập, mật khẩu, số tài khoản, số dư...</li><li>Trên Wi-Fi công cộng, kỹ thuật MITM (Man-in-the-Middle) cho phép kẻ tấn công đọc và thậm chí <strong>sửa đổi</strong> dữ liệu bạn gửi.</li></ul><p><strong>Tại sao HTTPS an toàn hơn:</strong></p><ul><li>Dữ liệu được <strong>mã hóa bằng TLS</strong> trước khi gửi đi.</li><li>Kẻ nghe lén chỉ thấy chuỗi ký tự vô nghĩa, không giải mã được nếu không có khóa.</li><li><strong>Xác thực máy chủ:</strong> HTTPS dùng chứng chỉ số (SSL Certificate) để chứng minh website là thật (không phải website giả mạo).</li></ul><hr><h3 id="cau-5-van-dung-thiet-ke-chinh-sach-bao-mat" tabindex="-1">Câu 5 (Vận dụng): Thiết kế chính sách bảo mật <a class="header-anchor" href="#cau-5-van-dung-thiet-ke-chinh-sach-bao-mat" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Thiết kế chính sách bảo mật&quot;">​</a></h3><blockquote><p>Bạn là quản trị viên IT của một trường học. Hãy đề xuất ít nhất <strong>5 biện pháp bảo mật</strong> để bảo vệ mạng và dữ liệu của trường. Giải thích lý do cho mỗi biện pháp.</p></blockquote><p><strong>Đáp án gợi ý:</strong></p><table tabindex="0"><thead><tr><th>STT</th><th>Biện pháp</th><th>Lý do</th></tr></thead><tbody><tr><td>1</td><td>Cài đặt Firewall tại cổng mạng</td><td>Ngăn chặn truy cập trái phép từ ngoài vào</td></tr><tr><td>2</td><td>Bắt buộc mật khẩu mạnh (8+ ký tự, phức tạp) cho tất cả tài khoản</td><td>Ngăn đoán/dò mật khẩu</td></tr><tr><td>3</td><td>Cài antivirus và cập nhật định kỳ trên mọi máy</td><td>Phát hiện và diệt malware</td></tr><tr><td>4</td><td>Sao lưu dữ liệu quan trọng hàng ngày (backup)</td><td>Phòng mất dữ liệu do ransomware, hỏng ổ cứng</td></tr><tr><td>5</td><td>Phân quyền truy cập: học sinh không được xóa file hệ thống</td><td>Ngăn vô tình hoặc cố ý phá hoại</td></tr><tr><td>6</td><td>Cập nhật hệ điều hành và phần mềm thường xuyên</td><td>Vá lỗ hổng bảo mật mà malware khai thác</td></tr><tr><td>7</td><td>Đào tạo nhận thức bảo mật cho giáo viên và học sinh</td><td>Phòng tránh phishing và social engineering</td></tr></tbody></table><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><h3 id="❌-loi-1-nham-virus-va-worm" tabindex="-1">❌ Lỗi 1: Nhầm Virus và Worm <a class="header-anchor" href="#❌-loi-1-nham-virus-va-worm" aria-label="Permalink to &quot;❌ Lỗi 1: Nhầm Virus và Worm&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Worm cần gắn vào file để lây lan.&quot;</p><p><strong>Đúng:</strong> <strong>Worm tự lây lan qua mạng</strong>, không cần file ký chủ, không cần người dùng thực hiện hành động. <strong>Virus</strong> mới cần gắn vào file và cần người dùng chạy file đó.</p><hr><h3 id="❌-loi-2-nghi-antivirus-la-đu-đe-bao-ve-hoan-toan" tabindex="-1">❌ Lỗi 2: Nghĩ Antivirus là đủ để bảo vệ hoàn toàn <a class="header-anchor" href="#❌-loi-2-nghi-antivirus-la-đu-đe-bao-ve-hoan-toan" aria-label="Permalink to &quot;❌ Lỗi 2: Nghĩ Antivirus là đủ để bảo vệ hoàn toàn&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Máy tính có Antivirus là an toàn tuyệt đối.&quot;</p><p><strong>Đúng:</strong> Antivirus là lớp bảo vệ quan trọng nhưng <strong>không đủ một mình</strong>. Còn cần: Firewall, cập nhật phần mềm, mật khẩu mạnh, 2FA, và thói quen dùng mạng an toàn. Nhiều virus mới (zero-day) chưa có trong cơ sở dữ liệu antivirus.</p><hr><h3 id="❌-loi-3-nghi-phishing-chi-qua-email" tabindex="-1">❌ Lỗi 3: Nghĩ Phishing chỉ qua email <a class="header-anchor" href="#❌-loi-3-nghi-phishing-chi-qua-email" aria-label="Permalink to &quot;❌ Lỗi 3: Nghĩ Phishing chỉ qua email&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Phishing chỉ xảy ra qua email.&quot;</p><p><strong>Đúng:</strong> Phishing có thể qua <strong>email, SMS (smishing), điện thoại (vishing), mạng xã hội, quảng cáo website</strong>. Bất kỳ kênh nào có thể giả mạo tổ chức uy tín để lừa lấy thông tin đều là phishing.</p><hr><h3 id="❌-loi-4-nham-firewall-voi-antivirus" tabindex="-1">❌ Lỗi 4: Nhầm Firewall với Antivirus <a class="header-anchor" href="#❌-loi-4-nham-firewall-voi-antivirus" aria-label="Permalink to &quot;❌ Lỗi 4: Nhầm Firewall với Antivirus&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Firewall kiểm tra file xem có virus không.&quot;</p><p><strong>Đúng:</strong> <strong>Firewall kiểm soát luồng dữ liệu</strong> vào/ra mạng (dựa trên IP, port, giao thức). <strong>Antivirus quét file/chương trình</strong> để tìm malware. Đây là hai công cụ khác nhau, bổ sung cho nhau, không thay thế nhau.</p><hr><h3 id="❌-loi-5-nghi-mat-khau-dai-la-mat-khau-manh" tabindex="-1">❌ Lỗi 5: Nghĩ mật khẩu dài là mật khẩu mạnh <a class="header-anchor" href="#❌-loi-5-nghi-mat-khau-dai-la-mat-khau-manh" aria-label="Permalink to &quot;❌ Lỗi 5: Nghĩ mật khẩu dài là mật khẩu mạnh&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mật khẩu &#39;aaaaaaaaaaaa&#39; (12 chữ a) là mạnh vì dài 12 ký tự.&quot;</p><p><strong>Đúng:</strong> Độ mạnh của mật khẩu phụ thuộc vào <strong>độ phức tạp và tính ngẫu nhiên</strong>, không chỉ độ dài. <code>aaaaaaaaaaaa</code> cực kỳ yếu vì kẻ tấn công dùng <strong>dictionary attack</strong> (tấn công từ điển) sẽ thử ngay. Mật khẩu mạnh cần kết hợp: chữ HOA, chữ thường, SỐ, ký tự đặc biệt, VÀ không có nghĩa rõ ràng.</p><hr><h3 id="❌-loi-6-nham-mat-khau-manh-voi-mat-khau-phuc-tap" tabindex="-1">❌ Lỗi 6: Nhầm mật khẩu mạnh với mật khẩu phức tạp <a class="header-anchor" href="#❌-loi-6-nham-mat-khau-manh-voi-mat-khau-phuc-tap" aria-label="Permalink to &quot;❌ Lỗi 6: Nhầm mật khẩu mạnh với mật khẩu phức tạp&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mật khẩu P@ssw0rd mạnh vì có chữ hoa, số, ký tự đặc biệt.&quot;</p><p><strong>Đúng:</strong> P@ssw0rd là <strong>mật khẩu yếu</strong> dù phức tạp về hình thức – nó nằm trong danh sách top mật khẩu phổ biến nhất. Mật khẩu mạnh thật sự cần: <strong>độ dài</strong> (12+ ký tự), <strong>ngẫu nhiên</strong>, không dùng từ trong từ điển. Passphrase như <code>con-chó-nhỏ-chạy-nhanh</code> dài và dễ nhớ nhưng khó brute-force hơn P@ssw0rd.</p><hr><h3 id="❌-loi-7-nghi-2fa-la-bat-kha-xam-pham" tabindex="-1">❌ Lỗi 7: Nghĩ 2FA là bất khả xâm phạm <a class="header-anchor" href="#❌-loi-7-nghi-2fa-la-bat-kha-xam-pham" aria-label="Permalink to &quot;❌ Lỗi 7: Nghĩ 2FA là bất khả xâm phạm&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Bật 2FA rồi thì tài khoản 100% an toàn, không cần lo gì.&quot;</p><p><strong>Đúng:</strong> 2FA tăng bảo mật đáng kể nhưng không hoàn hảo: <strong>SIM swap attack</strong> (kẻ tấn công thuyết phục nhà mạng chuyển số điện thoại), <strong>phishing real-time</strong> (trang giả lừa nhập cả OTP), <strong>malware đánh cắp TOTP seed</strong>. Xác thực hardware key (YubiKey) an toàn hơn SMS 2FA.</p><hr><h3 id="❌-loi-8-nham-dos-va-ddos" tabindex="-1">❌ Lỗi 8: Nhầm DoS và DDoS <a class="header-anchor" href="#❌-loi-8-nham-dos-va-ddos" aria-label="Permalink to &quot;❌ Lỗi 8: Nhầm DoS và DDoS&quot;">​</a></h3><p><strong>Sai:</strong> &quot;DoS và DDoS là cùng một loại tấn công.&quot;</p><p><strong>Đúng:</strong> <strong>DoS (Denial of Service)</strong> là tấn công từ <strong>một nguồn duy nhất</strong> – dễ chặn bằng cách block IP nguồn. <strong>DDoS (Distributed DoS)</strong> dùng <strong>hàng nghìn-triệu thiết bị</strong> (botnet) tấn công đồng thời – rất khó chặn vì không thể block hàng triệu IP hợp lệ. DDoS nguy hiểm hơn nhiều so với DoS đơn giản.</p><hr><h3 id="❌-loi-9-nghi-phishing-chi-xay-ra-qua-email" tabindex="-1">❌ Lỗi 9: Nghĩ phishing chỉ xảy ra qua email <a class="header-anchor" href="#❌-loi-9-nghi-phishing-chi-xay-ra-qua-email" aria-label="Permalink to &quot;❌ Lỗi 9: Nghĩ phishing chỉ xảy ra qua email&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tôi không mở email lạ nên không bị phishing.&quot;</p><p><strong>Đúng:</strong> Phishing xảy ra qua nhiều kênh: <strong>email</strong> (phổ biến nhất), <strong>SMS (smishing)</strong>, <strong>điện thoại (vishing – voice phishing)</strong>, <strong>mạng xã hội</strong>, <strong>trang web giả mạo</strong>. Thậm chí QR code (quishing) cũng được dùng. Cần cảnh giác trên tất cả kênh, không chỉ email.</p><hr><h3 id="❌-loi-10-nham-ma-hoa-va-an-du-lieu-obfuscation" tabindex="-1">❌ Lỗi 10: Nhầm mã hóa và ẩn dữ liệu (obfuscation) <a class="header-anchor" href="#❌-loi-10-nham-ma-hoa-va-an-du-lieu-obfuscation" aria-label="Permalink to &quot;❌ Lỗi 10: Nhầm mã hóa và ẩn dữ liệu (obfuscation)&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Đổi tên file thành file.xyz là đã mã hóa bảo vệ dữ liệu.&quot;</p><p><strong>Đúng:</strong> <strong>Đổi tên hay ẩn</strong> là obfuscation – không bảo vệ nội dung, ai có file vẫn đọc được bằng hex editor. <strong>Mã hóa thật</strong> (AES, RSA) biến dữ liệu thành chuỗi ngẫu nhiên không thể đọc được nếu không có key. Obfuscation ≠ Security – bảo mật không nên dựa vào sự bí ẩn.</p><hr><h3 id="❌-loi-11-nghi-https-nghia-la-website-đang-tin-cay" tabindex="-1">❌ Lỗi 11: Nghĩ HTTPS nghĩa là website đáng tin cậy <a class="header-anchor" href="#❌-loi-11-nghi-https-nghia-la-website-đang-tin-cay" aria-label="Permalink to &quot;❌ Lỗi 11: Nghĩ HTTPS nghĩa là website đáng tin cậy&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Website có ổ khóa xanh (HTTPS) là an toàn và đáng tin.&quot;</p><p><strong>Đúng:</strong> HTTPS chỉ xác nhận <strong>kết nối được mã hóa</strong> và <strong>domain là hợp lệ</strong>. Không xác nhận website đó không lừa đảo. Website phishing hoàn toàn có thể dùng HTTPS với SSL certificate hợp lệ (miễn phí từ Let&#39;s Encrypt). Luôn kiểm tra domain cẩn thận, không chỉ xem ổ khóa.</p><hr><h3 id="❌-loi-12-nham-tuong-lua-voi-ids-ips" tabindex="-1">❌ Lỗi 12: Nhầm tường lửa với IDS/IPS <a class="header-anchor" href="#❌-loi-12-nham-tuong-lua-voi-ids-ips" aria-label="Permalink to &quot;❌ Lỗi 12: Nhầm tường lửa với IDS/IPS&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tường lửa có thể phát hiện và ngăn chặn tấn công xâm nhập.&quot;</p><p><strong>Đúng:</strong> <strong>Firewall</strong> kiểm soát lưu lượng dựa trên quy tắc (allow/deny theo IP, port, giao thức). <strong>IDS (Intrusion Detection System)</strong> phát hiện hành vi tấn công nhưng không chặn. <strong>IPS (Intrusion Prevention System)</strong> phát hiện và <strong>chủ động chặn</strong> tấn công. Đây là 3 công cụ bảo mật khác nhau, cần dùng bổ sung nhau.</p><hr><h3 id="❌-loi-13-nghi-mat-khau-dai-hon-luon-an-toan-hon" tabindex="-1">❌ Lỗi 13: Nghĩ mật khẩu dài hơn luôn an toàn hơn <a class="header-anchor" href="#❌-loi-13-nghi-mat-khau-dai-hon-luon-an-toan-hon" aria-label="Permalink to &quot;❌ Lỗi 13: Nghĩ mật khẩu dài hơn luôn an toàn hơn&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mật khẩu 20 ký tự luôn an toàn hơn 8 ký tự.&quot;</p><p><strong>Đúng:</strong> Độ dài quan trọng, nhưng <strong>entropy (độ ngẫu nhiên)</strong> còn quan trọng hơn. Mật khẩu 20 ký tự <code>aaaaaaaaaaaaaaaaaaaaa</code> yếu hơn 8 ký tự ngẫu nhiên <code>K#9mX$qL</code>. Entropy = log2(kích_thước_bộ_ký_tự ^ độ_dài). Dùng password manager tạo mật khẩu ngẫu nhiên thật sự.</p><hr><h3 id="❌-loi-14-nham-sql-injection-voi-tan-cong-mang-thong-thuong" tabindex="-1">❌ Lỗi 14: Nhầm SQL Injection với tấn công mạng thông thường <a class="header-anchor" href="#❌-loi-14-nham-sql-injection-voi-tan-cong-mang-thong-thuong" aria-label="Permalink to &quot;❌ Lỗi 14: Nhầm SQL Injection với tấn công mạng thông thường&quot;">​</a></h3><p><strong>Sai:</strong> &quot;SQL Injection là tấn công mạng từ bên ngoài như DDoS.&quot;</p><p><strong>Đúng:</strong> <strong>SQL Injection</strong> là tấn công <strong>tầng ứng dụng</strong> – kẻ tấn công nhập mã SQL vào form web để thao túng database. Ví dụ: nhập <code>&#39; OR &#39;1&#39;=&#39;1</code> vào ô password để bypass đăng nhập. Firewall mạng không chặn được SQL Injection vì request trông &quot;bình thường&quot; về mặt mạng.</p><hr><h3 id="❌-loi-15-nghi-backup-la-giai-phap-bao-mat" tabindex="-1">❌ Lỗi 15: Nghĩ backup là giải pháp bảo mật <a class="header-anchor" href="#❌-loi-15-nghi-backup-la-giai-phap-bao-mat" aria-label="Permalink to &quot;❌ Lỗi 15: Nghĩ backup là giải pháp bảo mật&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Có backup rồi thì không cần lo về ransomware.&quot;</p><p><strong>Đúng:</strong> Backup giúp <strong>phục hồi</strong> sau tấn công nhưng không <strong>ngăn ngừa</strong> tấn công xảy ra. Ransomware hiện đại còn <strong>đánh cắp dữ liệu</strong> trước khi mã hóa (double extortion) – đe dọa công bố dữ liệu nhạy cảm ngay cả khi bạn có backup. Cần kết hợp backup + bảo mật toàn diện.</p><hr><h3 id="❌-loi-16-nham-trojan-voi-virus" tabindex="-1">❌ Lỗi 16: Nhầm Trojan với Virus <a class="header-anchor" href="#❌-loi-16-nham-trojan-voi-virus" aria-label="Permalink to &quot;❌ Lỗi 16: Nhầm Trojan với Virus&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Trojan là virus lây lan qua mạng tự động.&quot;</p><p><strong>Đúng:</strong> <strong>Virus</strong> tự nhân bản bằng cách gắn vào file và lây lan. <strong>Trojan</strong> giả mạo là phần mềm hợp lệ (game, phần mềm miễn phí) nhưng chứa payload độc hại – <strong>không tự lây lan</strong>, phụ thuộc người dùng tự cài. Trojan thường mở backdoor, đánh cắp dữ liệu, hoặc tải thêm malware.</p><hr><h3 id="❌-loi-17-nghi-public-wi-fi-an-toan-neu-dung-https" tabindex="-1">❌ Lỗi 17: Nghĩ public Wi-Fi an toàn nếu dùng HTTPS <a class="header-anchor" href="#❌-loi-17-nghi-public-wi-fi-an-toan-neu-dung-https" aria-label="Permalink to &quot;❌ Lỗi 17: Nghĩ public Wi-Fi an toàn nếu dùng HTTPS&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dùng HTTPS khi vào public Wi-Fi là hoàn toàn an toàn.&quot;</p><p><strong>Đúng:</strong> HTTPS bảo vệ <strong>nội dung</strong> nhưng còn nhiều rủi ro trên public Wi-Fi: kẻ tấn công có thể setup <strong>Evil Twin AP</strong> (mạng giả giống tên mạng thật), tiến hành <strong>SSL stripping</strong> (downgrade HTTPS về HTTP trước khi thiết lập kết nối), hoặc phân tích <strong>traffic patterns</strong> dù không đọc được nội dung. Dùng VPN trên public Wi-Fi là an toàn nhất.</p><hr><h3 id="❌-loi-18-nham-het-han-session-voi-đang-xuat" tabindex="-1">❌ Lỗi 18: Nhầm hết hạn session với đăng xuất <a class="header-anchor" href="#❌-loi-18-nham-het-han-session-voi-đang-xuat" aria-label="Permalink to &quot;❌ Lỗi 18: Nhầm hết hạn session với đăng xuất&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Đóng tab trình duyệt là đã đăng xuất khỏi tài khoản.&quot;</p><p><strong>Đúng:</strong> Đóng tab <strong>không xóa session cookie</strong>. Nếu mở lại trang, vẫn đang đăng nhập. <strong>Đăng xuất thật sự</strong> phải nhấn logout – server hủy session token. Đặc biệt quan trọng trên máy tính dùng chung. Nhiều trang web có <strong>session timeout</strong> tự động, nhưng không nên phụ thuộc vào đó.</p><hr><h3 id="❌-loi-19-nghi-cung-mat-khau-cho-nhieu-tai-khoan-la-on" tabindex="-1">❌ Lỗi 19: Nghĩ cùng mật khẩu cho nhiều tài khoản là ổn <a class="header-anchor" href="#❌-loi-19-nghi-cung-mat-khau-cho-nhieu-tai-khoan-la-on" aria-label="Permalink to &quot;❌ Lỗi 19: Nghĩ cùng mật khẩu cho nhiều tài khoản là ổn&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dùng một mật khẩu mạnh cho tất cả tài khoản vừa tiện vừa an toàn.&quot;</p><p><strong>Đúng:</strong> <strong>Credential stuffing</strong>: khi một website bị hack và mật khẩu bị lộ, kẻ tấn công thử mật khẩu đó trên mọi dịch vụ khác (Gmail, ngân hàng...). Một mật khẩu cho nhiều tài khoản nghĩa là một điểm thất bại duy nhất. Dùng <strong>password manager</strong> để có mật khẩu riêng cho mỗi tài khoản.</p><hr><h3 id="❌-loi-20-nham-ma-hoa-đoi-xung-voi-bat-đoi-xung" tabindex="-1">❌ Lỗi 20: Nhầm mã hóa đối xứng với bất đối xứng <a class="header-anchor" href="#❌-loi-20-nham-ma-hoa-đoi-xung-voi-bat-đoi-xung" aria-label="Permalink to &quot;❌ Lỗi 20: Nhầm mã hóa đối xứng với bất đối xứng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;RSA và AES đều là mã hóa, như nhau.&quot;</p><p><strong>Đúng:</strong> <strong>AES (mã hóa đối xứng)</strong>: cùng key để mã hóa và giải mã – nhanh, phù hợp cho dữ liệu lớn. <strong>RSA (mã hóa bất đối xứng)</strong>: public key mã hóa, private key giải mã – chậm hơn, dùng để trao đổi key và chữ ký số. TLS dùng RSA/ECDH để trao đổi AES key, rồi dùng AES để mã hóa toàn bộ dữ liệu.</p><hr><h3 id="❌-loi-21-nghi-chung-chi-ssl-mien-phi-kem-bao-mat-hon-tra-phi" tabindex="-1">❌ Lỗi 21: Nghĩ chứng chỉ SSL miễn phí kém bảo mật hơn trả phí <a class="header-anchor" href="#❌-loi-21-nghi-chung-chi-ssl-mien-phi-kem-bao-mat-hon-tra-phi" aria-label="Permalink to &quot;❌ Lỗi 21: Nghĩ chứng chỉ SSL miễn phí kém bảo mật hơn trả phí&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Let&#39;s Encrypt miễn phí nên kém bảo mật hơn SSL certificate trả tiền.&quot;</p><p><strong>Đúng:</strong> <strong>Let&#39;s Encrypt</strong> cung cấp DV (Domain Validation) certificates miễn phí, mã hóa mạnh như bất kỳ certificate trả phí nào. Sự khác biệt: certificate trả tiền có thể có OV (Organization Validation) hoặc EV (Extended Validation) – xác minh thêm thông tin tổ chức, hiển thị tên công ty trong browser. Mã hóa như nhau.</p><hr><h3 id="❌-loi-22-nham-social-engineering-voi-hack-ky-thuat" tabindex="-1">❌ Lỗi 22: Nhầm social engineering với hack kỹ thuật <a class="header-anchor" href="#❌-loi-22-nham-social-engineering-voi-hack-ky-thuat" aria-label="Permalink to &quot;❌ Lỗi 22: Nhầm social engineering với hack kỹ thuật&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Social engineering là hack máy tính bằng lỗ hổng phần mềm.&quot;</p><p><strong>Đúng:</strong> <strong>Social engineering</strong> tấn công <strong>con người</strong>, không phải máy tính – lừa nạn nhân tự mình cung cấp thông tin hoặc thực hiện hành động có hại. Ví dụ: giả vờ là IT support để lấy mật khẩu, hoặc tạo cảm giác khẩn cấp để nạn nhân click link độc hại. Đây là vector tấn công phổ biến nhất.</p><hr><h3 id="❌-loi-23-nghi-patch-update-phan-mem-khong-quan-trong" tabindex="-1">❌ Lỗi 23: Nghĩ patch/update phần mềm không quan trọng <a class="header-anchor" href="#❌-loi-23-nghi-patch-update-phan-mem-khong-quan-trong" aria-label="Permalink to &quot;❌ Lỗi 23: Nghĩ patch/update phần mềm không quan trọng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Phiên bản cũ vẫn hoạt động tốt, không cần update.&quot;</p><p><strong>Đúng:</strong> Nhiều bản update là <strong>bản vá bảo mật (security patch)</strong> cho lỗ hổng đã biết. Khi lỗ hổng bị công bố (CVE), kẻ tấn công ngay lập tức tấn công các hệ thống chưa vá (n-day exploit). WannaCry ransomware (2017) lây nhiễm các máy Windows chưa vá MS17-010 – đã có patch từ 2 tháng trước.</p><hr><h3 id="❌-loi-24-nham-ids-voi-firewall" tabindex="-1">❌ Lỗi 24: Nhầm IDS với firewall <a class="header-anchor" href="#❌-loi-24-nham-ids-voi-firewall" aria-label="Permalink to &quot;❌ Lỗi 24: Nhầm IDS với firewall&quot;">​</a></h3><p><strong>Sai:</strong> &quot;IDS là tên khác của firewall.&quot;</p><p><strong>Đúng:</strong> <strong>Firewall</strong> kiểm soát traffic theo quy tắc (allow/deny) – phòng thủ chủ động. <strong>IDS (Intrusion Detection System)</strong> giám sát traffic và log để phát hiện hành vi bất thường – cảnh báo, không tự chặn. IDS như camera giám sát; firewall như bảo vệ ở cổng. Cần cả hai.</p><hr><h3 id="❌-loi-25-nghi-xoa-file-la-xoa-hoan-toan" tabindex="-1">❌ Lỗi 25: Nghĩ xóa file là xóa hoàn toàn <a class="header-anchor" href="#❌-loi-25-nghi-xoa-file-la-xoa-hoan-toan" aria-label="Permalink to &quot;❌ Lỗi 25: Nghĩ xóa file là xóa hoàn toàn&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Xóa file vào Recycle Bin rồi empty là file mất hoàn toàn.&quot;</p><p><strong>Đúng:</strong> Khi xóa file, hệ điều hành chỉ đánh dấu vùng đĩa là &quot;trống&quot; – dữ liệu vẫn còn đó cho đến khi bị ghi đè. Dùng phần mềm phục hồi dữ liệu có thể khôi phục file đã &quot;xóa&quot;. Để xóa thật sự: dùng <strong>secure delete</strong> (ghi đè nhiều lần), hoặc mã hóa ổ đĩa từ đầu.</p><hr><h3 id="❌-loi-26-nham-zero-day-voi-n-day" tabindex="-1">❌ Lỗi 26: Nhầm zero-day với N-day <a class="header-anchor" href="#❌-loi-26-nham-zero-day-voi-n-day" aria-label="Permalink to &quot;❌ Lỗi 26: Nhầm zero-day với N-day&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mọi lỗ hổng bảo mật đều là zero-day.&quot;</p><p><strong>Đúng:</strong> <strong>Zero-day</strong>: lỗ hổng <strong>chưa được nhà sản xuất biết</strong> – không có patch, rất nguy hiểm. <strong>N-day</strong>: lỗ hổng <strong>đã được biết và có patch</strong> nhưng nhiều hệ thống chưa vá – vẫn nguy hiểm vì nhiều tổ chức chậm vá. Phần lớn cuộc tấn công thành công dùng N-day, không phải zero-day.</p><hr><h3 id="❌-loi-27-nghi-mang-noi-bo-an-toan-hoan-toan" tabindex="-1">❌ Lỗi 27: Nghĩ mạng nội bộ an toàn hoàn toàn <a class="header-anchor" href="#❌-loi-27-nghi-mang-noi-bo-an-toan-hoan-toan" aria-label="Permalink to &quot;❌ Lỗi 27: Nghĩ mạng nội bộ an toàn hoàn toàn&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mạng nội bộ (LAN) không cần bảo mật vì không ai từ ngoài vào được.&quot;</p><p><strong>Đúng:</strong> Nhiều mối đe dọa đến từ <strong>bên trong</strong>: nhân viên cố ý hoặc vô ý, thiết bị bị nhiễm malware kết nối vào mạng, USB từ bên ngoài cắm vào. <strong>Lateral movement</strong> – kẻ tấn công sau khi xâm nhập một máy sẽ di chuyển trong mạng nội bộ để tấn công thêm. Zero-trust networking: không tin tưởng mặc định ngay cả trong mạng nội bộ.</p><hr><h3 id="❌-loi-28-nham-authentication-voi-authorization" tabindex="-1">❌ Lỗi 28: Nhầm authentication với authorization <a class="header-anchor" href="#❌-loi-28-nham-authentication-voi-authorization" aria-label="Permalink to &quot;❌ Lỗi 28: Nhầm authentication với authorization&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Đăng nhập thành công là có quyền làm bất cứ điều gì.&quot;</p><p><strong>Đúng:</strong> <strong>Authentication (Xác thực)</strong>: xác nhận bạn là ai (đăng nhập thành công). <strong>Authorization (Phân quyền)</strong>: xác định bạn được phép làm gì sau khi đăng nhập. Nhân viên A đăng nhập thành công nhưng chỉ được truy cập phòng ban A, không được vào hồ sơ nhân sự của phòng B.</p><hr><h3 id="❌-loi-29-nghi-vpn-an-hoan-toan-danh-tinh" tabindex="-1">❌ Lỗi 29: Nghĩ VPN ẩn hoàn toàn danh tính <a class="header-anchor" href="#❌-loi-29-nghi-vpn-an-hoan-toan-danh-tinh" aria-label="Permalink to &quot;❌ Lỗi 29: Nghĩ VPN ẩn hoàn toàn danh tính&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dùng VPN là hoàn toàn ẩn danh trên Internet.&quot;</p><p><strong>Đúng:</strong> VPN ẩn IP thật của bạn khỏi website bạn truy cập, nhưng: <strong>VPN provider</strong> vẫn thấy toàn bộ traffic của bạn (nếu họ log), website vẫn có thể nhận dạng qua <strong>browser fingerprint</strong> (loại trình duyệt, fonts, plugins...), và hành vi đăng nhập vào tài khoản. VPN tăng quyền riêng tư nhưng không hoàn toàn ẩn danh.</p><hr><h3 id="❌-loi-30-nham-encryption-at-rest-voi-encryption-in-transit" tabindex="-1">❌ Lỗi 30: Nhầm encryption at rest với encryption in transit <a class="header-anchor" href="#❌-loi-30-nham-encryption-at-rest-voi-encryption-in-transit" aria-label="Permalink to &quot;❌ Lỗi 30: Nhầm encryption at rest với encryption in transit&quot;">​</a></h3><p><strong>Sai:</strong> &quot;HTTPS mã hóa dữ liệu cả khi lưu trữ và truyền tải.&quot;</p><p><strong>Đúng:</strong> <strong>Encryption in transit (HTTPS/TLS)</strong>: mã hóa dữ liệu <strong>khi đang truyền</strong> qua mạng. <strong>Encryption at rest</strong>: mã hóa dữ liệu <strong>khi lưu trữ</strong> trên ổ đĩa. Dữ liệu có thể được mã hóa khi truyền (HTTPS) nhưng lưu unencrypted trên server, hoặc ngược lại. Cần cả hai cho bảo mật toàn diện.</p><hr><h3 id="❌-loi-31-nghi-chi-can-đoi-mat-khau-sau-khi-bi-hack" tabindex="-1">❌ Lỗi 31: Nghĩ chỉ cần đổi mật khẩu sau khi bị hack <a class="header-anchor" href="#❌-loi-31-nghi-chi-can-đoi-mat-khau-sau-khi-bi-hack" aria-label="Permalink to &quot;❌ Lỗi 31: Nghĩ chỉ cần đổi mật khẩu sau khi bị hack&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Biết tài khoản bị hack, đổi mật khẩu là xong.&quot;</p><p><strong>Đúng:</strong> Sau khi bị hack cần: đổi mật khẩu (đương nhiên), <strong>kiểm tra thiết bị có malware không</strong>, thu hồi tất cả session/token đang hoạt động, kiểm tra email/số điện thoại recovery có bị thay đổi không, đổi mật khẩu các tài khoản khác dùng cùng mật khẩu, và <strong>kích hoạt 2FA</strong>.</p><hr><h3 id="❌-loi-32-nham-white-hat-va-black-hat-hacker" tabindex="-1">❌ Lỗi 32: Nhầm white hat và black hat hacker <a class="header-anchor" href="#❌-loi-32-nham-white-hat-va-black-hat-hacker" aria-label="Permalink to &quot;❌ Lỗi 32: Nhầm white hat và black hat hacker&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Hacker là người xấu, không có hacker tốt.&quot;</p><p><strong>Đúng:</strong> <strong>White hat hacker (ethical hacker)</strong>: tìm lỗ hổng bảo mật <strong>có ủy quyền</strong> để giúp tổ chức vá lỗi – đây là nghề nghiệp chuyên nghiệp (penetration tester). <strong>Black hat hacker</strong>: tấn công trái phép để trục lợi. <strong>Grey hat</strong>: ở giữa – tìm lỗ hổng không có phép nhưng thường báo cáo thay vì khai thác.</p><hr><h3 id="❌-loi-33-nghi-antivirus-phat-hien-đuoc-100-malware" tabindex="-1">❌ Lỗi 33: Nghĩ antivirus phát hiện được 100% malware <a class="header-anchor" href="#❌-loi-33-nghi-antivirus-phat-hien-đuoc-100-malware" aria-label="Permalink to &quot;❌ Lỗi 33: Nghĩ antivirus phát hiện được 100% malware&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Antivirus cài rồi thì chắc chắn phát hiện được tất cả virus.&quot;</p><p><strong>Đúng:</strong> Antivirus dựa vào signature-based detection – chỉ phát hiện malware <strong>đã biết</strong> trong cơ sở dữ liệu. <strong>Zero-day malware</strong> và <strong>polymorphic malware</strong> (tự thay đổi signature) có thể qua mặt antivirus. Tỷ lệ phát hiện của antivirus tốt nhất cũng chỉ đạt ~95-99%.</p><hr><h3 id="❌-loi-34-nham-data-breach-voi-data-loss" tabindex="-1">❌ Lỗi 34: Nhầm data breach với data loss <a class="header-anchor" href="#❌-loi-34-nham-data-breach-voi-data-loss" aria-label="Permalink to &quot;❌ Lỗi 34: Nhầm data breach với data loss&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Data breach và data loss là giống nhau – đều là mất dữ liệu.&quot;</p><p><strong>Đúng:</strong> <strong>Data loss (mất dữ liệu)</strong>: dữ liệu bị xóa, hỏng, không truy cập được – do lỗi phần cứng, xóa nhầm, thiên tai. <strong>Data breach (vi phạm dữ liệu)</strong>: dữ liệu bị <strong>lộ ra ngoài</strong> trái phép – bị đánh cắp, copy, truy cập bất hợp pháp. Data loss thường có thể phục hồi từ backup; data breach là vấn đề bảo mật và pháp lý nghiêm trọng.</p><hr><h3 id="❌-loi-35-nghi-firewall-rules-theo-chieu-outbound-khong-quan-trong" tabindex="-1">❌ Lỗi 35: Nghĩ firewall rules theo chiều outbound không quan trọng <a class="header-anchor" href="#❌-loi-35-nghi-firewall-rules-theo-chieu-outbound-khong-quan-trong" aria-label="Permalink to &quot;❌ Lỗi 35: Nghĩ firewall rules theo chiều outbound không quan trọng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Chỉ cần chặn traffic vào (inbound), traffic ra không cần kiểm soát.&quot;</p><p><strong>Đúng:</strong> <strong>Outbound filtering</strong> rất quan trọng: malware thường liên lạc với <strong>C&amp;C (Command &amp; Control) server</strong> ra ngoài Internet. Chặn outbound connections không được phép có thể ngăn malware đã nhiễm trong mạng giao tiếp với kẻ tấn công, giảm thiệt hại.</p><hr><h3 id="❌-loi-36-nham-sniffer-voi-malware" tabindex="-1">❌ Lỗi 36: Nhầm sniffer với malware <a class="header-anchor" href="#❌-loi-36-nham-sniffer-voi-malware" aria-label="Permalink to &quot;❌ Lỗi 36: Nhầm sniffer với malware&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Packet sniffer là malware dùng để tấn công.&quot;</p><p><strong>Đúng:</strong> <strong>Packet sniffer (như Wireshark)</strong> là công cụ <strong>hợp pháp</strong> dùng để phân tích mạng, gỡ lỗi, và bảo mật. Được dùng bởi sysadmin và security engineer. Tuy nhiên, hacker cũng dùng sniffer cho mục đích xấu (nghe lén traffic không mã hóa). Công cụ tự nó không xấu – mục đích sử dụng mới xác định đúng/sai.</p><hr><h3 id="❌-loi-37-nghi-password-hash-la-ma-hoa-đao-nguoc-đuoc" tabindex="-1">❌ Lỗi 37: Nghĩ password hash là mã hóa đảo ngược được <a class="header-anchor" href="#❌-loi-37-nghi-password-hash-la-ma-hoa-đao-nguoc-đuoc" aria-label="Permalink to &quot;❌ Lỗi 37: Nghĩ password hash là mã hóa đảo ngược được&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Nếu biết thuật toán hash, có thể giải mã hash để lấy mật khẩu gốc.&quot;</p><p><strong>Đúng:</strong> <strong>Hash là hàm một chiều (one-way function)</strong> – không thể đảo ngược toán học. Tuy nhiên, tấn công <strong>rainbow table</strong> (bảng hash tính sẵn) hoặc <strong>brute-force</strong> có thể tìm được mật khẩu gốc nếu mật khẩu yếu. Đây là lý do cần <strong>salt</strong> (giá trị ngẫu nhiên thêm vào trước khi hash) để vô hiệu hóa rainbow table.</p><hr><h3 id="❌-loi-38-nham-ket-noi-ssl-tls-voi-ket-noi-an-toan-hoan-toan" tabindex="-1">❌ Lỗi 38: Nhầm kết nối SSL/TLS với kết nối an toàn hoàn toàn <a class="header-anchor" href="#❌-loi-38-nham-ket-noi-ssl-tls-voi-ket-noi-an-toan-hoan-toan" aria-label="Permalink to &quot;❌ Lỗi 38: Nhầm kết nối SSL/TLS với kết nối an toàn hoàn toàn&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Kết nối TLS bảo vệ khỏi mọi tấn công mạng.&quot;</p><p><strong>Đúng:</strong> TLS bảo vệ <strong>tính bí mật và tính toàn vẹn</strong> trong quá trình truyền. Nhưng không bảo vệ khỏi: <strong>malware trên thiết bị</strong> (đã trên máy rồi, không cần nghe lén mạng), <strong>tấn công ứng dụng</strong> (SQL injection, XSS trong nội dung được mã hóa), hay <strong>lộ dữ liệu tại server</strong>.</p><hr><h3 id="❌-loi-39-nghi-tat-ca-email-tu-đia-chi-quen-thuoc-đeu-an-toan" tabindex="-1">❌ Lỗi 39: Nghĩ tất cả email từ địa chỉ quen thuộc đều an toàn <a class="header-anchor" href="#❌-loi-39-nghi-tat-ca-email-tu-đia-chi-quen-thuoc-đeu-an-toan" aria-label="Permalink to &quot;❌ Lỗi 39: Nghĩ tất cả email từ địa chỉ quen thuộc đều an toàn&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Email từ <a href="mailto:boss@company.com" target="_blank" rel="noreferrer">boss@company.com</a> chắc chắn là từ sếp tôi.&quot;</p><p><strong>Đúng:</strong> <strong>Email spoofing</strong>: kẻ tấn công có thể giả mạo địa chỉ From: để email trông như đến từ người bạn tin tưởng. Nếu domain thiếu <strong>SPF, DKIM, DMARC</strong> records, bất kỳ ai cũng có thể gửi email giả mạo. CEO Fraud (BEC – Business Email Compromise) là loại tấn công phổ biến dựa trên kỹ thuật này.</p><hr><h3 id="❌-loi-40-nham-mitm-voi-eavesdropping" tabindex="-1">❌ Lỗi 40: Nhầm MITM với eavesdropping <a class="header-anchor" href="#❌-loi-40-nham-mitm-voi-eavesdropping" aria-label="Permalink to &quot;❌ Lỗi 40: Nhầm MITM với eavesdropping&quot;">​</a></h3><p><strong>Sai:</strong> &quot;MITM và eavesdropping là cùng một tấn công.&quot;</p><p><strong>Đúng:</strong> <strong>Eavesdropping (nghe lén)</strong>: thụ động, chỉ quan sát traffic. <strong>MITM (Man-in-the-Middle)</strong>: chủ động, chen vào giữa hai bên giao tiếp, có thể <strong>đọc và sửa đổi</strong> traffic theo thời gian thực. MITM nghiêm trọng hơn – không chỉ nghe mà còn can thiệp vào nội dung giao tiếp.</p><hr><h3 id="❌-loi-41-nghi-http-strict-transport-security-hsts-khong-can-thiet" tabindex="-1">❌ Lỗi 41: Nghĩ HTTP Strict Transport Security (HSTS) không cần thiết <a class="header-anchor" href="#❌-loi-41-nghi-http-strict-transport-security-hsts-khong-can-thiet" aria-label="Permalink to &quot;❌ Lỗi 41: Nghĩ HTTP Strict Transport Security (HSTS) không cần thiết&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Đã có HTTPS rồi, không cần HSTS.&quot;</p><p><strong>Đúng:</strong> HSTS ngăn chặn <strong>SSL stripping attack</strong>: kẻ tấn công downgrade kết nối từ HTTPS xuống HTTP trong lần kết nối đầu tiên. Với HSTS, browser buộc dùng HTTPS ngay cả lần đầu tiên (sau lần truy cập đầu), không cho phép HTTP. HSTS là bổ sung quan trọng cho HTTPS.</p><hr><h3 id="❌-loi-42-nham-vulnerability-voi-exploit" tabindex="-1">❌ Lỗi 42: Nhầm vulnerability với exploit <a class="header-anchor" href="#❌-loi-42-nham-vulnerability-voi-exploit" aria-label="Permalink to &quot;❌ Lỗi 42: Nhầm vulnerability với exploit&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Vulnerability và exploit là cùng một thứ.&quot;</p><p><strong>Đúng:</strong> <strong>Vulnerability (lỗ hổng)</strong>: điểm yếu trong hệ thống có thể bị khai thác. <strong>Exploit</strong>: mã/kỹ thuật <strong>cụ thể</strong> để khai thác lỗ hổng đó. Lỗ hổng có thể tồn tại mà chưa có exploit (chưa bị khai thác). Exploit là &quot;công cụ&quot; tận dụng vulnerability.</p><hr><h3 id="❌-loi-43-nghi-captcha-ngan-chan-đuoc-tat-ca-bot" tabindex="-1">❌ Lỗi 43: Nghĩ captcha ngăn chặn được tất cả bot <a class="header-anchor" href="#❌-loi-43-nghi-captcha-ngan-chan-đuoc-tat-ca-bot" aria-label="Permalink to &quot;❌ Lỗi 43: Nghĩ captcha ngăn chặn được tất cả bot&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Có CAPTCHA là website an toàn khỏi bot và tấn công tự động.&quot;</p><p><strong>Đúng:</strong> CAPTCHA giúp giảm bot, nhưng: <strong>AI giải CAPTCHA</strong> ngày càng hiệu quả (Google reCAPTCHA bị phá nhiều lần), <strong>CAPTCHA farm</strong> (người thật giải CAPTCHA với giá thấp), và <strong>adversarial attacks</strong> cụ thể. CAPTCHA là một lớp bảo vệ, không phải giải pháp hoàn chỉnh chống bot.</p><hr><h3 id="❌-loi-44-nham-port-scanning-voi-tan-cong-mang" tabindex="-1">❌ Lỗi 44: Nhầm port scanning với tấn công mạng <a class="header-anchor" href="#❌-loi-44-nham-port-scanning-voi-tan-cong-mang" aria-label="Permalink to &quot;❌ Lỗi 44: Nhầm port scanning với tấn công mạng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Port scanning là tấn công hacker dùng để phá hoại hệ thống.&quot;</p><p><strong>Đúng:</strong> <strong>Port scanning</strong> là kỹ thuật khảo sát để biết cổng nào đang mở – là bước chuẩn bị (reconnaissance), không phải tấn công. Sysadmin dùng nmap để kiểm tra hệ thống của mình. Kẻ tấn công cũng dùng port scan để tìm mục tiêu. Công cụ hợp pháp, mục đích quyết định tính hợp pháp.</p><hr><h3 id="❌-loi-45-nghi-chi-can-bao-mat-lop-mang-la-đu" tabindex="-1">❌ Lỗi 45: Nghĩ chỉ cần bảo mật lớp mạng là đủ <a class="header-anchor" href="#❌-loi-45-nghi-chi-can-bao-mat-lop-mang-la-đu" aria-label="Permalink to &quot;❌ Lỗi 45: Nghĩ chỉ cần bảo mật lớp mạng là đủ&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Có firewall tốt là đủ bảo mật cho hệ thống.&quot;</p><p><strong>Đúng:</strong> Bảo mật cần theo nguyên tắc <strong>Defense in Depth (phòng thủ nhiều lớp)</strong>: bảo mật vật lý, bảo mật mạng (firewall, IDS), bảo mật ứng dụng (OWASP, WAF), bảo mật dữ liệu (mã hóa), bảo mật endpoint (antivirus, EDR), và quan trọng nhất là <strong>đào tạo nhận thức bảo mật</strong> cho con người.</p><hr><h3 id="❌-loi-46-nham-spyware-voi-adware" tabindex="-1">❌ Lỗi 46: Nhầm spyware với adware <a class="header-anchor" href="#❌-loi-46-nham-spyware-voi-adware" aria-label="Permalink to &quot;❌ Lỗi 46: Nhầm spyware với adware&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Spyware là phần mềm theo dõi quảng cáo.&quot;</p><p><strong>Đúng:</strong> <strong>Adware</strong> hiển thị quảng cáo không mong muốn – thường ít nguy hiểm hơn. <strong>Spyware</strong> bí mật <strong>thu thập thông tin</strong> như keystroke (keylogger), lịch sử duyệt web, screenshot, thông tin tài khoản – gửi về kẻ tấn công mà người dùng không biết. Spyware nguy hiểm hơn nhiều so với adware.</p><hr><h3 id="❌-loi-47-nghi-tor-hoan-toan-an-danh" tabindex="-1">❌ Lỗi 47: Nghĩ TOR hoàn toàn ẩn danh <a class="header-anchor" href="#❌-loi-47-nghi-tor-hoan-toan-an-danh" aria-label="Permalink to &quot;❌ Lỗi 47: Nghĩ TOR hoàn toàn ẩn danh&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dùng TOR Browser là hoàn toàn ẩn danh, không ai theo dõi được.&quot;</p><p><strong>Đúng:</strong> TOR tăng ẩn danh nhưng không hoàn hảo: <strong>exit node có thể nghe lén</strong> traffic không mã hóa, <strong>timing correlation attacks</strong> có thể de-anonymize người dùng bằng cách phân tích traffic vào/ra, và lỗ hổng trình duyệt có thể lộ IP thật. TOR + HTTPS + không đăng nhập tài khoản cá nhân mới tăng ẩn danh tốt.</p><hr><h3 id="❌-loi-48-nham-certificate-pinning-voi-certificate-transparency" tabindex="-1">❌ Lỗi 48: Nhầm certificate pinning với certificate transparency <a class="header-anchor" href="#❌-loi-48-nham-certificate-pinning-voi-certificate-transparency" aria-label="Permalink to &quot;❌ Lỗi 48: Nhầm certificate pinning với certificate transparency&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Certificate pinning và certificate transparency đều ngăn certificate giả.&quot;</p><p><strong>Đúng:</strong> <strong>Certificate pinning</strong>: ứng dụng chỉ chấp nhận certificate/public key cụ thể đã biết trước – ngăn MITM ngay cả với certificate từ CA hợp lệ. <strong>Certificate Transparency (CT)</strong>: log công khai tất cả certificate được cấp – giúp phát hiện certificate trái phép sau khi đã cấp. Hai cơ chế bổ sung nhau.</p><hr><h3 id="❌-loi-49-nghi-lo-hong-bao-mat-chi-do-code-xau" tabindex="-1">❌ Lỗi 49: Nghĩ lỗ hổng bảo mật chỉ do code xấu <a class="header-anchor" href="#❌-loi-49-nghi-lo-hong-bao-mat-chi-do-code-xau" aria-label="Permalink to &quot;❌ Lỗi 49: Nghĩ lỗ hổng bảo mật chỉ do code xấu&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Nếu code tốt thì không có lỗ hổng bảo mật.&quot;</p><p><strong>Đúng:</strong> Lỗ hổng đến từ nhiều nguồn: code logic (SQL injection, buffer overflow), <strong>cấu hình sai</strong> (default credentials, permissions quá rộng), <strong>thiết kế sai</strong> (thiếu rate limiting, thiếu input validation), <strong>phụ thuộc bên thứ ba</strong> (vulnerable library), và <strong>con người</strong> (social engineering). Code tốt chỉ giải quyết một phần.</p><hr><h3 id="❌-loi-50-nham-security-through-obscurity-la-đu" tabindex="-1">❌ Lỗi 50: Nhầm security through obscurity là đủ <a class="header-anchor" href="#❌-loi-50-nham-security-through-obscurity-la-đu" aria-label="Permalink to &quot;❌ Lỗi 50: Nhầm security through obscurity là đủ&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Giấu cổng SSH sang port 2222 thay vì 22 là biện pháp bảo mật tốt.&quot;</p><p><strong>Đúng:</strong> <strong>Security through obscurity</strong> (bảo mật bằng cách che giấu) là không đủ – port scan nhanh chóng tìm ra port nào đang mở. Che giấu port giảm noise trong log nhưng không tăng bảo mật thực sự. Nên kết hợp với: xác thực mạnh (SSH key thay mật khẩu), fail2ban, và whitelist IP nếu có thể.</p>`,322)])])}const p=t(o,[["render",g]]);export{d as __pageData,p as default};
